  'services.scopeTitle': 'Quels services apparaissent ici ?',
  'services.scope': 'Cette vue suit la parenté des processus, pas les dossiers des projets. Les agents et les terminaux sont les enfants directs du serveur Sillage ; tout ce qu’ils lancent est rangé sous eux, chaque commande avec son arbre de processus. Les services autonomes, les processus sous tmux ou screen et ceux confiés à une unité systemd autre qu’une app permanente (sillage-app-*) sont exclus. Un processus dont le lanceur a disparu reste visible tant que le service Sillage le tient. Fermer le navigateur n’arrête rien. Les commandes sont abrégées, sans l’enrobage du CLI, et les valeurs qui ressemblent à un secret sont masquées.',
