  "instructions.how.timing": "Une modification vaut pour les sessions qui démarrent ensuite : une session déjà ouverte garde la version qu'elle a reçue. OpenCode, qui les reçoit avec chaque message, la voit dès le suivant.",
  "instructions.how.vsMemory": "Consignes ou mémoire ? Les consignes sont les règles que tu fixes ; la mémoire, ce que les agents apprennent en travaillant.",
  "memory.how.what": "Les agents y notent d'eux-mêmes ce qui servira aux sessions suivantes : une préférence, une décision et sa raison, un piège rencontré. Un index, MEMORY.md, et une note par fichier.",
  "memory.how.claude": "Claude s'en sert comme de sa mémoire habituelle : Sillage lui indique ce dossier à la place de celui de ~/.claude. Il charge l'index au démarrage et ouvre les notes quand il en a besoin.",
  "memory.how.codex": "Codex n'a pas de mémoire de ce genre : Sillage lui donne l'index au démarrage, il lit les notes dans le dossier et écrit avec les outils write_memory et delete_memory, en te demandant de valider si sa politique d'approbation l'exige.",
  "memory.how.opencode": "OpenCode est dans le même cas : l'index lui arrive avec chaque message, il lit les notes dans le dossier et écrit avec les outils write_memory et delete_memory.",
  "memory.how.grok": "Grok Build reçoit l'index à la création de sa session, lit les notes dans le dossier et écrit avec les mêmes outils. Sa propre mémoire entre sessions n'est pas touchée.",
  "memory.how.scope": "Une mémoire par projet, commune à tous les CLI et à tous les worktrees du projet : ce que l'un apprend, les autres le savent.",
  "memory.how.import": "Au premier lancement, la mémoire que Claude tenait déjà pour la racine du projet est copiée ici. L'original reste en place.",
  "memory.how.edit": "Corrige ou supprime une note devenue fausse : sinon elle orientera les sessions suivantes avec l'autorité d'un fait.",
  'schedule.cadence.webhook': "À chaque appel de son webhook",
