  "schedule.check.remove": "Retirer",
  "schedule.check.description": "Un script que Sillage joue avant de réveiller l’agent, pour qu’un tir ne coûte une session que s’il y a quelque chose à faire : une version publiée, un fichier changé, un test qui casse. Sortir en {skip} veut dire « rien à faire ».",
  "schedule.check.starter": "#!/usr/bin/env bash\n# Joué avant chaque tour, à la racine du projet. Sortie 0 : réveiller l’agent.\n# Sortie 10 : rien à faire, pas de session (la première ligne affichée sert de raison).\n# Tout autre code est une erreur : rien n’est lancé.\n# Ce que tu affiches arrive à l’agent ; {{check_output}} le place dans le prompt.\n# $SILLAGE_STATE_DIR est conservé d’un tir à l’autre, pour comparer avec la dernière fois.\n\nlatest=$(npm view @openai/codex version) || exit 2\nlast=$(cat \"$SILLAGE_STATE_DIR/version\" 2>/dev/null)\n[ \"$latest\" = \"$last\" ] && { echo \"Toujours $latest\"; exit 10; }\necho \"$latest\" > \"$SILLAGE_STATE_DIR/version\"\necho \"Nouvelle version : $latest (précédente : ${last:-inconnue})\"\n",
  "schedule.check.contract": "Shell par défaut, tout langage avec un shebang. Sortie 0 : l’agent est réveillé ; {skip} : le tir est écarté ; tout autre code : erreur. Variables : SILLAGE_STATE_DIR, SILLAGE_FIRED_AT, SILLAGE_TRIGGER, SILLAGE_PREVIOUS_RUN_AT, SILLAGE_PROJECT_DIR.",
