  'onboarding.rules.title': "Consignes et mémoire",
  'onboarding.rules.lead': "Au début de chaque session, un agent reçoit trois choses : deux que tu lui imposes, une qu’il tient lui-même. Chacune se règle à part.",
  'onboarding.rules.suggest.language': "Réponds dans ma langue",
  'onboarding.rules.suggest.language.text': "- Réponds dans la langue dans laquelle j’écris.",
  'onboarding.rules.suggest.commits': "Commits à l’infinitif",
  'onboarding.rules.suggest.commits.text': "- Titres de commit à l’infinitif, corps qui explique le pourquoi.",
  'onboarding.rules.suggest.verify': "Vérifie avant d’annoncer",
  'onboarding.rules.suggest.verify.text': "- Lance les tests et le typecheck avant d’annoncer qu’une chose fonctionne.",
  'onboarding.rules.suggest.why': "Commentaires : le pourquoi",
  'onboarding.rules.suggest.why.text': "- Des commentaires qui disent pourquoi, pas quoi.",
  'onboarding.rules.suggest.short': "Réponses courtes",
  'onboarding.rules.suggest.short.text': "- Réponses courtes : la conclusion d’abord, les détails ensuite.",
  'onboarding.rules.suggest.files': "Pas de fichiers d’outil dans le dépôt",
  'onboarding.rules.suggest.files.text': "- N’ajoute aucun fichier de configuration d’outil au dépôt sans me demander.",
  'onboarding.rules.suggest.coauthor': "Pas de co-auteur modèle",
  'onboarding.rules.suggest.coauthor.text': "- N’ajoute pas de ligne Co-Authored-By ni de signature de modèle dans les commits.",
  'onboarding.rules.suggest.nocommit': "Pas de commit sans demande",
  'onboarding.rules.suggest.nocommit.text': "- Ne commite ni ne pousse sans que je le demande.",
  'onboarding.rules.suggest.deps': "Pas de dépendance sans demande",
  'onboarding.rules.suggest.deps.text': "- N’ajoute pas de dépendance sans me demander d’abord.",
  'onboarding.rules.suggest.tests': "Les tests viennent avec le changement",
  'onboarding.rules.suggest.tests.text': "- Ajoute ou mets à jour les tests à chaque changement de comportement.",
  'onboarding.rules.suggest.scope': "Seulement ce qui est demandé",
  'onboarding.rules.suggest.scope.text': "- Ne refactorise ni ne réécris ce que je n’ai pas demandé ; dis-le si tu penses qu’il le faudrait.",
  'onboarding.address.title.both': "Adresse et téléphone",
  'onboarding.address.title.phone': "Depuis ton téléphone",
  'onboarding.address.lead.admin': "Sillage donne des liens vers lui-même : dans les notifications, dans les webhooks à coller sur GitHub, dans les réponses de son API, aux agents qui te font suivre une page. Il lui faut une adresse qui marche depuis ailleurs que cette machine.",
  'onboarding.address.lead.member': "Sillage est fait pour être suivi de partout : un tour lancé du bureau se termine depuis le canapé, et l’agent continue même quand l’écran est verrouillé.",
  'onboarding.address.public': "Adresse publique",
  'onboarding.address.public.explain': "C’est celle que Sillage mettra dans ses liens, et la seule sur laquelle il répondra une fois enregistrée. Change-la si tu es arrivé par une adresse provisoire.",
  'onboarding.address.moves': "Tu es connecté par {current}. Une fois cette adresse enregistrée, Sillage ne répond plus que sur elle : la visite vérifie qu’elle répond, puis t’y emmène pour te reconnecter et continuer.",
  'onboarding.address.unreachable': "Cette adresse ne répond pas d’ici. Rien n’a été enregistré.",
  'onboarding.address.public.keep': "Rien n’est enregistré pour une adresse locale : Sillage continue de déduire la sienne de la connexion, d’où que tu arrives. Dès que tu auras une adresse HTTPS, rejoue cette visite depuis Réglages › À propos pour la fixer.",
  'onboarding.address.invalid': "Une adresse http(s) sans chemin, par exemple https://sillage.exemple.fr.",
  'onboarding.address.reachable': "HTTPS, joignable de partout",
  'onboarding.address.localHttps': "Réseau local seulement",
  'onboarding.address.local': "Réseau local, sans HTTPS",
  'onboarding.address.noHttps': "Sans HTTPS",
  'onboarding.address.https.title': "Joignable, mais pas en HTTPS.",
  'onboarding.address.https.body': "Sans HTTPS, le téléphone ne peut ni installer l’app ni recevoir de notifications, et les connexions circulent en clair. Tailscale Serve donne une adresse HTTPS à l’instance en une commande ; un proxy comme Caddy aussi.",
  'onboarding.address.https.member': "Sans HTTPS, le téléphone ne peut ni installer l’app ni recevoir de notifications. C’est à un administrateur de donner une adresse HTTPS à l’instance (Tailscale Serve, un proxy).",
  'onboarding.address.reachable.tip': "Si cette adresse n’est joignable que chez toi, le guide d’accès à distance couvre Tailscale, un VPN existant ou Cloudflare Tunnel : rien à changer ici, seulement la route.",
  'onboarding.address.tailscale.title': "Joignable seulement sur ton réseau.",
  'onboarding.address.tailscale.body': "Hors de chez toi le téléphone ne l’atteindra pas, et sans HTTPS il ne peut ni installer l’app ni recevoir de notifications. Le plus simple : Tailscale, un réseau privé entre tes appareils, gratuit pour un usage personnel, dix minutes à mettre en place. Rien à ouvrir sur ta box.",
  'onboarding.address.tailscale.member': "Hors de chez toi le téléphone ne l’atteindra pas, et sans HTTPS il ne peut ni installer l’app ni recevoir de notifications. C’est à un administrateur de donner une adresse HTTPS à l’instance (Tailscale, VPN, tunnel).",
  'onboarding.address.tailscale.comment': "sur {host}, une fois Tailscale installé et connecté",
  'onboarding.address.tailscale.others': "Déjà un VPN, ou tu préfères Cloudflare Tunnel ?",
  'onboarding.address.guide': "Le guide d’accès à distance",
  'onboarding.address.install.title': "Installer comme une app",
  'onboarding.address.install.qr': "Code QR de l’adresse de l’instance",
  'onboarding.address.install.scan': "Scanne pour ouvrir l’adresse sur le téléphone, puis :",
  'onboarding.address.install.ios': "Safari › Partager › Sur l’écran d’accueil",
  'onboarding.address.install.android': "Chrome › menu › Installer l’application",
  'onboarding.address.install.why': "Plein écran, une icône Sillage, et sur iPhone c’est la condition pour recevoir les notifications.",
  'onboarding.address.notifications.title': "Notifications",
  'onboarding.address.notifications.phone': "À refaire une fois sur le téléphone, depuis l’app installée : Réglages › Notifications.",
  'onboarding.ready.title': "C’est prêt.",
  'onboarding.ready.lead': "Sillage est réglé. Tout ce qui suit se retrouve dans Réglages, et la visite se rejoue depuis Réglages › À propos.",
  'onboarding.ready.account': "Compte",
  'onboarding.ready.appearance': "Apparence",
  'onboarding.ready.agents': "Agents",
  'onboarding.ready.work': "Permissions",
