  'onboarding.step.remote': "Tes autres appareils",
  'onboarding.step.remote.sub': "Téléphone, autre poste",
  'onboarding.remote.title': "Depuis tes autres appareils",
  'onboarding.remote.lead': "Sillage Desktop n’écoute que sur cet ordinateur. Pour suivre un tour depuis ton téléphone ou un autre poste, il peut s’ouvrir à tes propres appareils par Tailscale, un réseau privé entre eux, gratuit pour un usage personnel. Rien n’est ouvert sur ta box.",
  'onboarding.remote.tip': "Facultatif, et coupé tant que tu ne l’actives pas : ça se change à tout moment dans Réglages › Accès distant. Les notifications sur le téléphone n’existent pas dans l’édition Desktop.",
  'onboarding.ready.remote': "Accès distant",
  'onboarding.ready.remote.off': "Désactivé · cet ordinateur seulement",
