  'onboarding.ready.next.skills': "Installer un skill ou un serveur MCP, le même pour tous les CLI",
  'onboarding.ready.next.schedule': "Planifier une tâche, ou la déclencher par un webhook",
  'onboarding.recommended': "recommandé",
  'onboarding.welcome.cli.title': "Tes CLI, tels quels",
  'onboarding.welcome.cli.body': "{names} : leurs abonnements, leurs outils et leurs permissions restent les leurs. Sillage les lance et te montre ce qu’ils font.",
  'onboarding.welcome.project.title': "Un projet, plusieurs conversations",
  'onboarding.welcome.project.body': "Un projet est un dossier de {host}. Plusieurs agents peuvent y travailler en même temps, chacun dans son worktree, avec les fichiers, le diff, Git et un terminal à côté de la conversation.",
  'onboarding.welcome.anywhere.title': "Suivi de partout",
  'onboarding.welcome.anywhere.body': "Un tour lancé au bureau continue navigateur fermé. Tu le reprends depuis le téléphone, et une notification te prévient quand l’agent attend ta décision.",
  'onboarding.welcome.local.title': "Tout reste sur cet ordinateur",
  'onboarding.welcome.local.body': "Ni serveur à tenir ni compte à créer : Sillage tourne sur ce poste, avec tes dossiers et tes CLI. Tes autres appareils peuvent le rejoindre par Tailscale, si tu le veux.",
  'onboarding.welcome.tour': "La visite règle l’essentiel en quelques écrans. Rien n’y est définitif : tout se retrouve dans Réglages.",
  'onboarding.agents.checking': "Vérification…",
  'onboarding.agents.cli.unknown': "Connexion à vérifier",
  'onboarding.agents.beginner.member': "Demande à un administrateur d’installer un CLI sur ce serveur : les installations lui reviennent.",
  'onboarding.agents.about.claude': "Le CLI d’Anthropic · abonnement Claude ou clé API",
  'onboarding.agents.about.codex': "Le CLI d’OpenAI · abonnement ChatGPT ou clé API",
  'onboarding.agents.about.opencode': "CLI open source · tes propres fournisseurs de modèles",
  'onboarding.agents.about.grok': "Le CLI de xAI · compte xAI ou clé API",
  'onboarding.agents.about.antigravity': "L’agent de Google · compte Google ou clé API",
  'onboarding.rules.general': "Consignes générales",
  'onboarding.memory.instructions.body': "Chaque projet a les siennes, qui s’ajoutent aux consignes générales. Elles vivent soit dans Sillage, soit dans le dépôt.",
  'onboarding.memory.memory.body': "Ce que les agents notent d’eux-mêmes en travaillant (pièges, décisions, conventions) et relisent à la session suivante. Chaque projet a la sienne ; il n’y en a pas pour toute l’instance.",
  'onboarding.rules.scope.instance': "toute l’instance",
  'onboarding.rules.scope.project': "propre à chaque projet",
  'onboarding.rules.default': "Ton défaut pour un nouveau projet",
  'onboarding.rules.default.hint': "chaque projet peut en décider autrement depuis sa page",
  'onboarding.rules.general.body': "Un seul texte, écrit ici, lu par tous les CLI dans tous les projets. Les agents peuvent le compléter quand tu leur donnes une consigne durable.",
  'onboarding.rules.general.member': "Un seul texte, lu par tous les CLI dans tous les projets. Un administrateur le tient ; tu le lis dans Réglages › Consignes.",
  'onboarding.ready.lead.noProject': "Sillage est réglé. Il ne manque qu’un projet pour lancer ta première conversation.",
