  'consumption.method.title': 'Comment c’est calculé',
  'consumption.method': 'Chaque tour terminé enregistre les tokens traités par chaque modèle, tels que le CLI les annonce. Le coût applique à ces tokens le prix public standard actuel du modèle, lectures et écritures de cache à leur propre tarif : une correction de prix corrige donc aussi le passé. Il ignore les paliers de long contexte, le traitement prioritaire et les outils facturés à la requête comme la recherche web. Avec un abonnement, rien de tout cela n’est facturé : c’est ce que le même travail coûterait par l’API.',
